package io.quarkus.deployment.annotations;

/**
 * Enum that specifies at what time generated bytecode should be run
 *
 * @deprecated Use the {@code ActionBuilder} service model with {@code Phase} and phase-based
 *             ordering instead.
 */
@Deprecated(since = "4.0")
public enum ExecutionTime {
    /**
     * The bytecode is run from a generated static initializer
     */
    STATIC_INIT,
    /**
     * The bytecode is run from a main method
     */
    RUNTIME_INIT
}
